  1	import type { IncomingMessage, ServerResponse } from 'node:http';
  2	import type { Router } from '../router.js';
  3	import type { RepositoryManager } from '../../models/repository/repository.manager.js';
  4	import { NotFoundError } from '../../errors.js';
  5	import { parseJsonBody, sendJson, sendError, isPlainObject } from '../requestUtils.js';
  6	import type { Repository } from '../../models/repository/repository.types.js';
  7	import type { AppConfig, GitCredentialEntry } from '../../config/config.types.js';
  8	import { extractHost } from '../../git/git-credentials.js';
  9	
 10	// ---------------------------------------------------------------------------
 11	// Route registration
 12	// ---------------------------------------------------------------------------
 13	
 14	/**
 15	 * Registers the five standard CRUD routes for the `/api/repositories` resource
 16	 * group on the provided `Router` instance, plus two credential-management
 17	 * routes that require access to the application configuration.
 18	 *
 19	 * All handlers delegate to the supplied `RepositoryManager` and map results
 20	 * or errors to the appropriate HTTP status codes:
 21	 *
 22	 * | Method | Path                                        | Success | Failure |
 23	 * |--------|---------------------------------------------|---------|---------|
 24	 * | GET    | /api/repositories                           | 200     | —       |
 25	 * | GET    | /api/repositories/:id                       | 200     | 404     |
 26	 * | POST   | /api/repositories                           | 201     | 400     |
 27	 * | PUT    | /api/repositories/:id                       | 200     | 404     |
 28	 * | DELETE | /api/repositories/:id                       | 204     | 404     |
 29	 * | POST   | /api/repositories/:id/refresh-timestamp     | 200     | 404     |
 30	 * | PUT    | /api/repositories/:id/credential            | 200     | 400/404 |
 31	 * | GET    | /api/repositories/:id/credential-options    | 200     | 404     |
 32	 */
 33	export function registerRepositoryRoutes(
 34	    router: Router,
 35	    repoManager: RepositoryManager,
 36	    appConfig: AppConfig,
 37	): void {
 38	    /**
 39	     * Look up a repository by ID.
 40	     *
 41	     * Sends a `404` response and returns `undefined` when the repository
 42	     * cannot be found.
 43	     *
 44	     * @param res          - The outgoing HTTP response (used to send the 404 error).
 45	     * @param repositoryId - The ID of the repository to look up.
 46	     * @returns The matching `Repository` on success, or `undefined` when a 404
 47	     *          has already been written to `res`.
 48	     */
 49	    function resolveRepository(
 50	        res: ServerResponse,
 51	        repositoryId: string,
 52	    ): Repository | undefined {
 53	        const repo = repoManager.getById(repositoryId);
 54	        if (repo === undefined) {
 55	            sendError(res, 404, `Repository with ID "${repositoryId}" not found.`);
 56	            return undefined;
 57	        }
 58	        return repo;
 59	    }
 60	
 61	    // ------------------------------------------------------------------
 62	    // GET /api/repositories — list all
 63	    // ------------------------------------------------------------------
 64	    router.get('/api/repositories', (
 65	        _req: IncomingMessage,
 66	        res: ServerResponse,
 67	        _params: Record<string, string>,
 68	    ): void => {
 69	        const repos = repoManager.list();
 70	        sendJson(res, 200, repos);
 71	    });
 72	
 73	    // ------------------------------------------------------------------
 74	    // GET /api/repositories/:id — get one
 75	    // ------------------------------------------------------------------
 76	    router.get('/api/repositories/:id', (
 77	        _req: IncomingMessage,
 78	        res: ServerResponse,
 79	        params: Record<string, string>,
 80	    ): void => {
 81	        const repo = resolveRepository(res, params['id']);
 82	        if (repo === undefined) return;
 83	        sendJson(res, 200, repo);
 84	    });
 85	
 86	    // ------------------------------------------------------------------
 87	    // POST /api/repositories — create
 88	    // ------------------------------------------------------------------
 89	    router.post('/api/repositories', async (
 90	        req: IncomingMessage,
 91	        res: ServerResponse,
 92	        _params: Record<string, string>,
 93	    ): Promise<void> => {
 94	        let body: unknown;
 95	        try {
 96	            body = await parseJsonBody(req);
 97	        } catch (err) {
 98	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
 99	            return;
100	        }

101	
102	        if (!isPlainObject(body)) {
103	            sendError(res, 400, 'Request body must be a JSON object.');
104	            return;
105	        }
106	
107	        const { url, name, id } = body as {
108	            url?: unknown;
109	            name?: unknown;
110	            id?: unknown;
111	        };
112	
113	        if (typeof url !== 'string' || url.trim() === '') {
114	            sendError(res, 400, 'Missing required field: url (non-empty string).');
115	            return;
116	        }
117	
118	        const params: { url: string; name?: string; id?: string } = { url: url.trim() };
119	        if (typeof name === 'string') params.name = name;
120	        if (typeof id === 'string') params.id = id;
121	
122	        try {
123	            const repo = repoManager.add(params);
124	            sendJson(res, 201, repo);
125	        } catch (err) {
126	            sendError(res, 400, err instanceof Error ? err.message : 'Could not create repository.');
127	        }
128	    });
129	
130	    // ------------------------------------------------------------------
131	    // PUT /api/repositories/:id — update
132	    // ------------------------------------------------------------------
133	    router.put('/api/repositories/:id', async (
134	        req: IncomingMessage,
135	        res: ServerResponse,
136	        params: Record<string, string>,
137	    ): Promise<void> => {
138	        const id = params['id'];
139	
140	        if (!repoManager.exists(id)) {
141	            sendError(res, 404, `Repository with ID "${id}" not found.`);
142	            return;
143	        }
144	
145	        let body: unknown;
146	        try {
147	            body = await parseJsonBody(req);
148	        } catch (err) {
149	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
150	            return;
151	        }
152	
153	        if (!isPlainObject(body)) {
154	            sendError(res, 400, 'Request body must be a JSON object.');
155	            return;
156	        }
157	
158	        const { name } = body as { name?: unknown };
159	
160	        if (typeof name !== 'string' || name.trim() === '') {
161	            sendError(res, 400, 'Missing required field: name (non-empty string).');
162	            return;
163	        }
164	
165	        try {
166	            const updated = repoManager.update(id, { name: name.trim() });
167	            sendJson(res, 200, updated);
168	        } catch (err) {
169	            // update() throws NotFoundError if the ID was removed
170	            // between the exists() check and the update() call (race condition).
171	            if (err instanceof NotFoundError) {
172	                sendError(res, 404, err.message);
173	            } else {
174	                sendError(res, 500, 'Internal server error.');
175	            }
176	        }
177	    });
178	
179	    // ------------------------------------------------------------------
180	    // DELETE /api/repositories/:id — delete
181	    // ------------------------------------------------------------------
182	    router.delete('/api/repositories/:id', (
183	        _req: IncomingMessage,
184	        res: ServerResponse,
185	        params: Record<string, string>,
186	    ): void => {
187	        const id = params['id'];
188	
189	        try {
190	            repoManager.remove(id);
191	        } catch (err) {
192	            if (err instanceof NotFoundError) {
193	                sendError(res, 404, `Repository with ID "${id}" not found.`);
194	            } else {
195	                sendError(res, 500, 'Internal server error.');
196	            }
197	            return;
198	        }
199	
200	        // 204 No Content — no body
201	        res.writeHead(204, {});
202	        res.end('');
203	    });
204	
205	    // ------------------------------------------------------------------
206	    // POST /api/repositories/:id/refresh-timestamp — record manual refresh
207	    //   Writes the current timestamp to LastRefreshedAt for the repository.
208	    //   Called by the GUI whenever the user triggers a manual refresh on
209	    //   the repository detail screen.
210	    // ------------------------------------------------------------------
211	    router.post('/api/repositories/:id/refresh-timestamp', (
212	        _req: IncomingMessage,
213	        res: ServerResponse,
214	        params: Record<string, string>,
215	    ): void => {
216	        const id = params['id'];
217	        try {
218	            const updated = repoManager.touchRefreshTimestamp(id);
219	            sendJson(res, 200, updated);
220	        } catch (err) {
221	            if (err instanceof NotFoundError) {
222	                sendError(res, 404, err.message);
223	            } else {
224	                sendError(res, 500, 'Internal server error.');
225	            }
226	        }
227	    });
228	
229	    // ------------------------------------------------------------------
230	    // PUT /api/repositories/:id/credential — set or clear credential
231	    //
232	    //   Accepts `{ credentialId: string | null }`.
233	    //   - When `credentialId` is a non-empty string, validates that it
234	    //     references an existing entry in `appConfig.gitCredentials`, then
235	    //     calls `RepositoryManager.updateCredential()` to persist the
236	    //     association.
237	    //   - When `credentialId` is `null`, clears the association.
238	    //   Returns the updated `Repository` on success (200).
239	    // ------------------------------------------------------------------
240	    router.put('/api/repositories/:id/credential', async (
241	        req: IncomingMessage,
242	        res: ServerResponse,
243	        params: Record<string, string>,
244	    ): Promise<void> => {
245	        const id = params['id'];
246	
247	        const repo = resolveRepository(res, id);
248	        if (repo === undefined) return;
249	
250	        let body: unknown;
251	        try {
252	            body = await parseJsonBody(req);
253	        } catch (err) {
254	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
255	            return;
256	        }
257	
258	        if (!isPlainObject(body)) {
259	            sendError(res, 400, 'Request body must be a JSON object.');
260	            return;
261	        }
262	
263	        const { credentialId } = body as { credentialId?: unknown };
264	
265	        if (credentialId !== null && typeof credentialId !== 'string') {
266	            sendError(res, 400, 'Missing required field: credentialId (string or null).');
267	            return;
268	        }
269	
270	        if (typeof credentialId === 'string') {
271	            // Validate that the referenced credential exists in the config.
272	            const credentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
273	            const exists = credentials.some((c) => c.id === credentialId);
274	            if (!exists) {
275	                sendError(
276	                    res,
277	                    400,
278	                    `Credential with ID "${credentialId}" does not exist in the application configuration.`,
279	                );
280	                return;
281	            }
282	        }
283	
284	        try {
285	            const updated = repoManager.updateCredential(id, credentialId as string | null);
286	            sendJson(res, 200, updated);
287	        } catch (err) {
288	            if (err instanceof NotFoundError) {
289	                sendError(res, 404, err.message);
290	            } else {
291	                sendError(res, 500, 'Internal server error.');
292	            }
293	        }
294	    });
295	
296	    // ------------------------------------------------------------------
297	    // GET /api/repositories/:id/credential-options — list matching credentials
298	    //
299	    //   Returns the subset of `appConfig.gitCredentials` whose `host` matches
300	    //   the hostname of the repository's remote URL.  Tokens are masked (replaced
301	    //   with `"***"`) before being sent to the client.
302	    //
303	    //   Response shape:
304	    //     {
305	    //       credentials: GitCredentialEntry[],  // token masked
306	    //       autoSelected?: string               // id of the sole matching credential
307	    //     }
308	    //
309	    //   `autoSelected` is included only when exactly one credential matches the
310	    //   repository's host.
311	    // ------------------------------------------------------------------
312	    router.get('/api/repositories/:id/credential-options', (
313	        _req: IncomingMessage,
314	        res: ServerResponse,
315	        params: Record<string, string>,
316	    ): void => {
317	        const id = params['id'];
318	
319	        const repo = resolveRepository(res, id);
320	        if (repo === undefined) return;
321	
322	        const credentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
323	        const repoHost = extractHost(repo.Url);
324	
325	        // Filter to credentials whose host matches the repository's URL host.
326	        // For non-HTTPS URLs (e.g. SSH), repoHost is null and no credentials match.
327	        const matching = repoHost !== null
328	            ? credentials.filter((c) => c.host === repoHost)
329	            : [];
330	
331	        // Mask tokens before sending — never expose raw tokens over the API.
332	        const maskedCredentials: GitCredentialEntry[] = matching.map((c) => ({
333	            ...c,
334	            token: '***',
335	        }));
336	
337	        const responseBody: { credentials: GitCredentialEntry[]; autoSelected?: string } = {
338	            credentials: maskedCredentials,
339	        };
340	
341	        if (matching.length === 1) {
342	            responseBody.autoSelected = matching[0].id;
343	        }
344	
345	        sendJson(res, 200, responseBody);
346	    });
347	}

