102	     * @throws {Error} If a repository with the same URL already exists.
103	     */
104	    add(params: { url: string; name?: string; id?: string }): Repository {
105	        const store = this.load();
106	
107	        let id = params.id;
108	        if (id) {
109	            id = id.trim();
110	            if (!isValidKebabCase(id)) {
111	                throw new Error(
112	                    `Invalid repository ID "${id}": must be a valid kebab-case string ` +
113	                    `(lowercase alphanumeric segments separated by single hyphens).`
114	                );
115	            }
116	        } else {
117	            id = inferSlugFromUrl(params.url);
118	            if (id === '') {
119	                throw new Error(
120	                    `Cannot infer a repository ID from URL "${redactUrl(params.url)}": the URL produced an empty slug. ` +
121	                    `Please provide an explicit ID.`
122	                );
123	            }
124	        }
125	
126	        const name = params.name ?? id;
127	
128	        // Strip embedded credentials from the URL before storing.
129	        let cleanUrl = params.url;
