168	
169	        if (index === -1) {
170	            throw new NotFoundError(`Cannot update: repository with ID "${id}" does not exist.`);
171	        }
172	
173	        store.Repositories[index] = { ...store.Repositories[index], Name: params.name };
174	        this.save(store);
175	        return store.Repositories[index];
176	    }
177	
178	    /**
179	     * Removes the repository with the given ID from the store.
180	     *
181	     * @throws {Error} If no repository with the given ID exists.
182	     */
183	    remove(id: string): void {
184	        const store = this.load();
185	        const index = store.Repositories.findIndex((r) => r.Id === id);
186	
187	        if (index === -1) {
188	            throw new NotFoundError(`Cannot remove: repository with ID "${id}" does not exist.`);
189	        }
