233	    }
234	
235	    /**
236	     * Writes the current UTC timestamp to `LastRefreshedAt` for the given
237	     * repository. Called when the user triggers a manual refresh from the
238	     * repository detail view.
239	     *
240	     * @throws {NotFoundError} If no repository with the given ID exists.
241	     */
242	    touchRefreshTimestamp(id: string): Repository {
