 56	/**
 57	 * Writes a JSON response with the given HTTP status code.
 58	 * Always sets `Content-Type: application/json`.
 59	 */
 60	export function sendJson(res: ServerResponse, status: number, data: unknown): void {
 61	    const body = JSON.stringify(data);
 62	    res.writeHead(status, {
 63	        'Content-Type': 'application/json',
 64	        'Content-Length': Buffer.byteLength(body),
 65	    });
 66	    res.end(body);
 67	}
 68	
 69	/**
 70	 * Sends a JSON error response with the shape `{ error: string }`.
 71	 */
 72	export function sendError(res: ServerResponse, status: number, message: string): void {
 73	    sendJson(res, status, { error: message });
 74	}
 75	
 76	/**
 77	 * Matches `url` against a `:named`-segment pattern (e.g. `/repos/:id/branches/:branch`)
 78	 * and returns an object mapping each named segment to its captured value.
 79	 * Returns `null` when the URL does not match the pattern.
 80	 *
 81	 * Only the **pathname** portion of the URL is compared — query strings and
 82	 * trailing slashes on the pattern side are not supported.
 83	 *
 84	 * Examples:
 85	 *   extractParams('/repos/:id', '/repos/42')         → { id: '42' }
 86	 *   extractParams('/repos/:id', '/repos/42/extra')   → null
 87	 *   extractParams('/repos/:id', '/other/42')         → null
 88	 */
 89	export function extractParams(
 90	    pattern: string,
 91	    url: string,
 92	): Record<string, string> | null {
 93	    // Strip query string from the incoming URL
 94	    const pathname = url.split('?')[0];
 95	
 96	    const patternSegments = pattern.split('/');
 97	    const urlSegments = pathname.split('/');
 98	
 99	    if (patternSegments.length !== urlSegments.length) {
100	        return null;

101	 * @returns The matching `GitCredentialEntry`, or `null` when resolution fails.
102	 *
103	 * @remarks
104	 * **SECURITY — host/credential coherence (explicit `credentialId` path):**
105	 * When `credentialId` is supplied, resolution performs only an exact `id` match;
106	 * no cross-validation against the URL's hostname is performed. A caller could
107	 * inadvertently (or maliciously) pass a `credentialId` belonging to a different
108	 * host and receive a credential for that host. The caller is responsible for
109	 * ensuring the URL's host is consistent with the credential's configured `host`
110	 * before using the resolved token. This validation should occur at the call site
111	 * (e.g. in the orchestrators) before passing the authenticated URL to git.
112	 */
113	export function resolveCredential(
114	    url: string,
115	    credentials: GitCredentialEntry[],
116	    credentialId?: string,
117	): GitCredentialEntry | null {
118	    if (credentialId !== undefined) {
119	        return credentials.find((c) => c.id === credentialId) ?? null;
120	    }
121	
122	    const host = extractHost(url);
123	    if (host === null) return null;
124	
125	    const matches = credentials.filter((c) => c.host === host);
126	    return matches.length === 1 ? matches[0] : null;
127	}
128	
129	/**
130	 * Injects a single token into an HTTPS URL as the userinfo component.
131	 *
132	 * This is the simplified successor to `injectCredentials()`. It accepts a
133	 * pre-resolved token string directly (obtained from a {@link GitCredentialEntry}
134	 * via {@link resolveCredential}) instead of the full credentials map.
135	 *
136	 * The token is written as the WHATWG URL username only (no password component)
137	 * since Personal Access Tokens are typically passed in the username field.
138	 * Special characters in the token are automatically percent-encoded by the
139	 * URL serialiser — no string concatenation is used.
140	 *
141	 * @param url   - The remote URL to modify.
142	 * @param token - The credential token to inject.
143	 * @returns The URL with the token injected, or the original URL unchanged for
144	 *   non-HTTPS or malformed URLs.
145	 */
146	export function injectCredentialToken(url: string, token: string): string {
147	    const host = extractHost(url);
148	    if (host === null) return url;
149	
150	    try {
151	        const parsed = new URL(url);
152	        parsed.username = token;
153	        parsed.password = '';
154	        return parsed.toString();
155	    } catch {
156	        return url;
157	    }
158	}
159	
160	/**
161	 * Returns `true` when the URL contains an embedded username (and optional password)
162	 * in the userinfo section (e.g. `https://token@github.com/...`).
163	 *
164	 * Always returns `false` for non-HTTPS or malformed URLs.
165	 *
166	 * @param url - The URL to inspect.
167	 */
168	export function hasEmbeddedCredentials(url: string): boolean {
169	    if (!url) return false;
170	    try {
171	        const parsed = new URL(url);
172	        if (parsed.protocol !== 'https:') return false;
173	        return parsed.username !== '';
174	    } catch {
175	        return false;
176	    }
177	}
178	
179	/**
180	 * Redacts embedded HTTPS credentials from a URL or arbitrary string (e.g. a
181	 * git error message such as `"fatal: repository 'https://token@host/...' not found"`).
182	 *
183	 * Pure HTTPS URLs are sanitised via the WHATWG URL object (clean user/password
184	 * removal). All other inputs — non-HTTPS URLs, prose strings, and unparseable
185	 * values — fall through to a regex scrub that replaces any `https?://…@` pattern
186	 * with `https://***@`, preserving the host and path while redacting the token.
187	 *
188	 * @param input - The URL or string to sanitise.
189	 * @returns The sanitised string, or the original if no embedded credentials are
190	 *   found.
191	 */
192	export function stripEmbeddedCredentials(input: string): string {
193	    if (!input) return input;
194	    try {
195	        const parsed = new URL(input);
196	        if (parsed.protocol === 'https:') {
197	            parsed.username = '';
198	            parsed.password = '';
199	            return parsed.toString();
200	        }
201	        // Non-HTTPS valid URL (e.g. git:// or a prose string the WHATWG parser
202	        // accepted with a non-standard scheme like "fatal:") — fall through to
203	        // the regex scrub below to redact any embedded https credentials.
204	    } catch {
205	        // Not parseable as a URL — fall through to regex scrub.
206	    }
207	    // Scrub any embedded https credential patterns present in prose strings
208	    // (e.g. git error: "fatal: repository 'https://token@host/...' not found").
209	    return input.replace(/(https?:\/\/)[^@\s]*@/g, '$1***@');
210	}

